1	package darksafe
2	
3	import (
4		"encoding/json"
5		"math"
6		"strings"
7		"testing"
8	)
9	
10	// 本文件回归保障区间均值查询的舍入行为：平均值以成功写入后存储的 float64 数值
11	// 为依据，精确算术平均舍入到最近的 float64；精确平均恰在两个相邻可表示值正中时，
12	// 取二进制有效数字末位为零的那个值（最近偶数舍入），正数与负数遵循同一规则。
13	// 极小值与零的精确平均舍入为零时保留符号（+0 与 -0），而数值完全抵消、
14	// 精确平均本来就是零时结果为 +0（见 TestQueryAverageExactZeroIsPositiveZero）。
15	
16	// TestQueryAverageMidpointRoundsToNearestEven 覆盖普通数值的中点舍入：
17	// 同一序列在两个不同时间戳写入一对相邻 float64，精确平均恰在两者正中，
18	// 分别保护向较小值与向较大值舍入的情形，且负数不改变取偶数的含义。
19	func TestQueryAverageMidpointRoundsToNearestEven(t *testing.T) {
20		cases := []struct {
21			name string
22			a, b string  // 写入的 JSON 数值字面量
23			want float64 // 期望的平均值
24		}{
25			// 精确平均 1.0000000000000001 在 1（末位偶）与 1.0000000000000002（末位奇）
26			// 正中：向较小值舍入为 1。朴素 float64 求和 (1+1.0000000000000002)/2 会
27			// 先舍入和再除，结果同样巧合为 1，但这里保障的是精确平均的取偶规则。
28			{"positive tie rounds down to even", "1", "1.0000000000000002", 1},
29			// 精确平均 1.0000000000000003 在 1.0000000000000002（末位奇）与
30			// 1.0000000000000004（末位偶）正中：向较大值舍入。
31			{"positive tie rounds up to even", "1.0000000000000002", "1.0000000000000004", 1.0000000000000004},
32			// 负数遵循同一取偶规则：-1 的有效数字末位为零，向零方向（较大值）舍入。
33			{"negative tie rounds to even toward zero", "-1", "-1.0000000000000002", -1},
34			// -1.0000000000000004 末位为偶，向远离零方向（较小值）舍入。
35			{"negative tie rounds to even away from zero", "-1.0000000000000002", "-1.0000000000000004", -1.0000000000000004},
36		}
37		for _, tc := range cases {
38			t.Run(tc.name, func(t *testing.T) {
39				store := NewMetricStore()
40				mustOK(t, store, `[
41					{"name":"m","timestamp":1,"value":`+tc.a+`},
42					{"name":"m","timestamp":2,"value":`+tc.b+`}
43				]`)
44				res := mustQuery(t, store, `{"op":"query","name":"m","start":1,"end":2}`)
45				if len(res.Series) != 1 {
46					t.Fatalf("series = %+v, want exactly one", res.Series)
47				}
48				s0 := res.Series[0]
49				if s0.Count != 2 {
50					t.Fatalf("count = %d, want 2", s0.Count)
51				}
52				if math.IsInf(s0.Average, 0) || math.IsNaN(s0.Average) {
53					t.Fatalf("average must be finite, got %v", s0.Average)
54				}
55				if s0.Average != tc.want {
56					t.Fatalf("average of %s and %s = %v, want %v (round half to even)",
57						tc.a, tc.b, s0.Average, tc.want)
58				}
59			})
60		}
61	}
62	
63	// TestQueryAverageSubnormalTieKeepsZeroSign 覆盖极小值与零的中点舍入：
64	// 5e-324 是最小的正 float64，它与 0 的精确平均（2^-1075）在 0 与该值正中，
65	// 最近偶数舍入为 +0；-5e-324 对称地舍入为 -0。两者数值相等，但符号必须保留，
66	// JSON 输出分别为 0 与 -0。
67	func TestQueryAverageSubnormalTieKeepsZeroSign(t *testing.T) {
68		cases := []struct {
69			name        string
70			value       string // 与 0 配对的极小值字面量
71			wantNeg     bool   // 期望结果符号位
72			wantAvgJSON string // 期望结果中 average 字段的 JSON 文本
73		}{
74			{"smallest positive rounds to positive zero", "5e-324", false, `"average":0`},
75			{"smallest negative rounds to negative zero", "-5e-324", true, `"average":-0`},
76		}
77		for _, tc := range cases {
78			t.Run(tc.name, func(t *testing.T) {
79				store := NewMetricStore()
80				mustOK(t, store, `[
81					{"name":"m","timestamp":1,"value":`+tc.value+`},
82					{"name":"m","timestamp":2,"value":0}
83				]`)
84				res := mustQuery(t, store, `{"op":"query","name":"m","start":1,"end":2}`)
85				if len(res.Series) != 1 {
86					t.Fatalf("series = %+v, want exactly one", res.Series)
87				}
88				s0 := res.Series[0]
89				if s0.Count != 2 {
90					t.Fatalf("count = %d, want 2", s0.Count)
91				}
92				if s0.Average != 0 || math.Signbit(s0.Average) != tc.wantNeg {
93					t.Fatalf("average of %s and 0 = %v (signbit=%v), want zero with signbit=%v",
94						tc.value, s0.Average, math.Signbit(s0.Average), tc.wantNeg)
95				}
96				b, err := json.Marshal(res)
97				if err != nil {
98					t.Fatal(err)
99				}
100				if !strings.Contains(string(b), tc.wantAvgJSON) {
101					t.Fatalf("query result JSON = %s, want it to contain %s", b, tc.wantAvgJSON)
102				}
103			})
104		}
105	}
106	
107	// TestQueryRoundingOnlyCountsPointsInRange 确认参与平均的点须位于查询闭区间内：
108	// 区间外的点不影响点数与舍入结果；单点区间中非零有限值的平均仍是该点的值。
109	func TestQueryRoundingOnlyCountsPointsInRange(t *testing.T) {
110		store := NewMetricStore()
111		// 同一序列三个点；ts=3 的点在查询区间 [1,2] 之外。
112		// 若它参与平均，count 会为 3 且均值远离中点舍入结果 1。
113		mustOK(t, store, `[
114			{"name":"m","timestamp":1,"value":1},
115			{"name":"m","timestamp":2,"value":1.0000000000000002},
116			{"name":"m","timestamp":3,"value":7}
117		]`)
118	
119		res := mustQuery(t, store, `{"op":"query","name":"m","start":1,"end":2}`)
120		if len(res.Series) != 1 {
121			t.Fatalf("series = %+v, want exactly one", res.Series)
122		}
123		if res.Series[0].Count != 2 || res.Series[0].Average != 1 {
124			t.Fatalf("range [1,2] = count %d average %v, want count 2 average 1 (out-of-range point must not participate)",
125				res.Series[0].Count, res.Series[0].Average)
126		}
127	
128		// 单点区间：非零有限值的平均就是该点存储的值本身。
129		res = mustQuery(t, store, `{"op":"query","name":"m","start":2,"end":2}`)
130		if len(res.Series) != 1 || res.Series[0].Count != 1 || res.Series[0].Average != 1.0000000000000002 {
131			t.Fatalf("single-point range [2,2] = %+v, want count 1 average 1.0000000000000002", res.Series)
132		}
133		res = mustQuery(t, store, `{"op":"query","name":"m","start":3,"end":3}`)
134		if len(res.Series) != 1 || res.Series[0].Count != 1 || res.Series[0].Average != 7 {
135			t.Fatalf("single-point range [3,3] = %+v, want count 1 average 7", res.Series)
136		}
137	}
138

